package vn.rtr.aeris.betaworkbench04;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
/** Immutable body generations, CAS pointer, no authority and no automatic deletion. */
public final class WorkspaceStore {
 public static final int MAX_BODY=2097152,MAX_GENERATIONS=16;public static final long QUOTA=8L*1024*1024,RESERVE=128L*1024*1024;
 public interface DirectorySync{void sync(File dir)throws IOException;}
 public interface Fault{void at(String point)throws IOException;}
 public static final class Snapshot{public final String status,head,body,sha;public final int sequence;Snapshot(String s,String h,String b,String x,int n){status=s;head=h;body=b;sha=x;sequence=n;}}
 private final File root;private final DirectorySync sync;private final Fault fault;private final long quota;private boolean latched=false;
 public WorkspaceStore(File dir,DirectorySync s,Fault f)throws IOException{this(dir,s,f,QUOTA);}
 public WorkspaceStore(File dir,DirectorySync s,Fault f,long limit)throws IOException{if(limit<1024||limit>QUOTA)throw new IOException("QUOTA_MUST_NOT_EXCEED_PRODUCTION_LIMIT");File expected=new File(dir.getParentFile().getCanonicalFile(),dir.getName());root=dir.getCanonicalFile();if(!root.equals(expected))throw new IOException("STORE_ROOT_SYMLINK");sync=s;fault=f;quota=limit;if(!root.exists()&&!root.mkdir())throw new IOException("STORE_CREATE");if(!root.isDirectory())throw new IOException("STORE_DIRECTORY");}
 public static String sha(byte[]b){try{byte[]d=MessageDigest.getInstance("SHA-256").digest(b);StringBuilder t=new StringBuilder();for(byte v:d)t.append(String.format(Locale.ROOT,"%02x",v&255));return t.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 public static byte[] read(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]b=new byte[16384];int n;while((n=in.read(b))!=-1){if(n==0)continue;if(out.size()+n>max)throw new IOException("BYTE_BOUND");out.write(b,0,n);}return out.toByteArray();}
 private byte[] bytes(File f,int max)throws IOException{try(InputStream in=new FileInputStream(f)){return read(in,max);}}
 private File child(String n)throws IOException{File f=new File(root,n);if(!f.getCanonicalFile().equals(f.getAbsoluteFile()))throw new IOException("STORE_SYMLINK");return f;}
 public synchronized Snapshot load()throws IOException{
  if(latched)throw new IOException("STORE_UNKNOWN_READONLY");File[]files=root.listFiles();if(files==null)throw new IOException("STORE_LIST");File head=child("HEAD");if(files.length==0)return new Snapshot("EMPTY","ROOT",null,null,0);
  long used=0;Map<Integer,File> bodies=new HashMap<>();for(File f:files){child(f.getName());if(!f.isFile())throw new IOException("STORE_FOREIGN_ENTRY");used+=f.length();if(used>quota)throw new IOException("STORE_QUOTA_READONLY");if(f.getName().endsWith(".pending")||f.getName().equals("UNKNOWN"))throw new IOException("STORE_PENDING_READONLY");if(f.getName().equals("HEAD"))continue;if(!f.getName().matches("[0-9]{4}-[a-f0-9]{64}\\.json"))throw new IOException("STORE_FOREIGN_ENTRY");int seq=Integer.parseInt(f.getName().substring(0,4));if(seq<1||seq>MAX_GENERATIONS||bodies.put(seq,f)!=null)throw new IOException("STORE_GENERATION_COLLISION");byte[]b=bytes(f,MAX_BODY);if(!sha(b).equals(f.getName().substring(5,69)))throw new IOException("STORE_BODY_SHA");}
  if(!head.isFile())throw new IOException("STORE_ORPHAN_READONLY");byte[]h=bytes(head,512);String text=new String(h,StandardCharsets.UTF_8);if(!text.matches("[1-9][0-9]? [a-f0-9]{64}\\n"))throw new IOException("STORE_HEAD_SHAPE");String[]parts=text.trim().split(" ");int seq=Integer.parseInt(parts[0]);if(bodies.size()!=seq||!bodies.containsKey(seq))throw new IOException("STORE_ROLLBACK_OR_ORPHAN_READONLY");for(int i=1;i<=seq;i++)if(!bodies.containsKey(i))throw new IOException("STORE_HISTORY_GAP");File body=bodies.get(seq);if(!body.getName().substring(5,69).equals(parts[1]))throw new IOException("STORE_HEAD_BODY");byte[]b=bytes(body,MAX_BODY);return new Snapshot("COMMITTED",sha(h),new String(b,StandardCharsets.UTF_8),parts[1],seq);
 }
 private void publish(File f,byte[]b,boolean replace)throws IOException{if(f.exists()&&!replace)throw new IOException("IMMUTABLE_EXISTS");File temp=child(f.getName()+".pending");if(!temp.createNewFile())throw new IOException("PENDING_EXISTS");try(FileOutputStream out=new FileOutputStream(temp)){out.write(b);out.getFD().sync();}fault.at("BEFORE_RENAME_"+f.getName());if(!temp.renameTo(f))throw new IOException("ATOMIC_RENAME_FAILED");sync.sync(root);}
 public synchronized Snapshot save(String expectedHead,String body)throws IOException{
  Snapshot old=load();if(!old.head.equals(expectedHead))throw new IOException("STORE_CAS_MISMATCH");byte[]b=body.getBytes(StandardCharsets.UTF_8);if(b.length>MAX_BODY)throw new IOException("BODY_BOUND");String digest=sha(b);if(digest.equals(old.sha))return old;long used=0;for(File f:root.listFiles())used+=f.length();if(used+b.length+1024>quota||old.sequence>=MAX_GENERATIONS||root.getUsableSpace()<RESERVE+b.length)throw new IOException("STORE_QUOTA_RESERVE_NO_AUTO_DELETE");
  try{File dest=child(String.format(Locale.ROOT,"%04d-%s.json",old.sequence+1,digest));publish(dest,b,false);fault.at("AFTER_BODY_BEFORE_HEAD");publish(child("HEAD"),((old.sequence+1)+" "+digest+"\n").getBytes(StandardCharsets.UTF_8),true);fault.at("AFTER_HEAD_SYNC");return load();}catch(IOException e){latched=true;try{File mark=child("UNKNOWN");if(mark.createNewFile())try(FileOutputStream out=new FileOutputStream(mark)){out.write(e.getMessage().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}sync.sync(root);}catch(Exception ignored){}throw e;}
 }
}
